mapper.select:
SELECT p.id, p.bar_id, p.user_id, p.title, p.content, p.city, p.is_top, p.status, p.like_count, p.favorite_count, p.comment_count, p.view_count, p.created_at, p.last_comment_time, b.name AS bar_name, u.nickname AS author_nickname, u.icon AS author_icon FROM post p JOIN bar b ON p.bar_id = b.id JOIN `user` u ON p.user_id = u.id WHERE p.status IN (1, 2)
AND b.status = 1
AND p.bar_id = #{barId}
AND p.user_id = #{userId}
AND p.city = #{city}
AND (p.title LIKE CONCAT('%', #{keyword}, '%') OR p.content LIKE CONCAT('%', #{keyword}, '%'))
ORDER BY p.is_top DESC, p.last_comment_time DESC, p.created_at DESC
